-- Code generated by factory from specs/sales/list-top-stores/spec.yaml. DO NOT EDIT.

-- name: ListTopStores :many
SELECT t2.store_code, t2.amount
FROM (
    SELECT t1.store_code AS store_code, t1.amount AS amount
    FROM daily_sales AS t1
    WHERE (t1.sales_date = sqlc.arg(sales_date)::date)
) AS t2
ORDER BY t2.amount DESC, t2.store_code DESC
LIMIT 3;
